class Dog:
    def bark(self):
        print("Woof!")
Dog().bark()

class Student:
    def __init__(self, name):
        self.name = name
print(Student("Ada").name)

class Counter:
    def __init__(self):
        self.value = 0
    def increment(self):
        self.value += 1
c = Counter()
c.increment()
c.increment()
print(c.value)

class Greeter:
    def hello():
        print("Hello!")
Greeter().hello()

class Box:
    def __init__(self, label):
        self.label = label
a = Box("A")
b = Box("B")
print(a.label, b.label)

class Student:
    def __init__(self, name):
        self.name = name
        self.scores = []
    def add_score(self, score):
        self.scores.append(score)
    def average(self):
        return sum(self.scores) / len(self.scores)
s = Student("Ada")
s.add_score(90)
s.add_score(80)
print(s.average())

class BankAccount:
    bank_name = "EduBank"
    def __init__(self, owner):
        self.owner = owner
a = BankAccount("Ada")
print(a.bank_name)

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price
    def __str__(self):
        return f"Product({self.name}, Rs.{self.price})"
print(Product("Mouse", 499))

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    def area(self):
        return self.width * self.height
print(Rectangle(4, 5).area())

class BankAccount:
    def __init__(self, balance):
        self.balance = balance
    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
acc = BankAccount(100)
acc.deposit(50)
print(acc.balance)

class User:
    def __init__(self, name, role):
        self.name = name.strip().title()
        self.role = role.strip().lower()
    def is_admin(self):
        return self.role == "admin"
print(User("  ada  ", "Admin").is_admin())

class Prompt:
    def __init__(self, text):
        self.text = text.strip()
    def length(self):
        return len(self.text)
print(Prompt("  hi  ").length())

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return "..."
class Cat(Animal):
    def speak(self):
        return "Meow"
print(Cat("Misty").speak())

class Animal:
    def __init__(self, name):
        self.name = name
class Cat(Animal):
    pass
misty = Cat("Misty")
print(misty.name)
print(isinstance(misty, Animal))

class Employee:
    def __init__(self, name, role):
        self.name = name
        self.role = role
class Manager(Employee):
    def __init__(self, name, team_size):
        super().__init__(name, "Manager")
        self.team_size = team_size
m = Manager("Sam", 5)
print(m.role, m.team_size)

class Engine:
    def start(self):
        return "engine started"
class Car:
    def __init__(self, model):
        self.model = model
        self.engine = Engine()
    def start(self):
        return f"{self.model}: {self.engine.start()}"
print(Car("Sedan").start())

class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius
    def to_fahrenheit(self):
        return self._celsius * 9 / 5 + 32
print(Temperature(0).to_fahrenheit())

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    def area(self):
        return self.width * self.height
    def describe(self):
        return f"area={self.area()}"
print(Rectangle(3, 3).describe())

class BankAccount:
    def __init__(self, balance):
        self.balance = balance
    def withdraw(self, amount):
        if amount <= self.balance:
            self.balance -= amount
            return True
        return False
acc = BankAccount(100)
print(acc.withdraw(30))
print(acc.balance)
print(acc.withdraw(1000))

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def move(self, dx, dy):
        self.x += dx
        self.y += dy
p = Point(2, 3)
p.move(1, -1)
print(p.x, p.y)

class Student:
    def __init__(self, name):
        self.name = name
print(type(Student("Ada")).__name__)

